WITH all_war AS ( SELECT player_ID, name_common, year_ID, SUM(WAR) AS season_war FROM ( SELECT player_ID, name_common, year_ID, WAR FROM batting WHERE WAR IS NOT NULL UNION ALL SELECT player_ID, name_common, year_ID, WAR FROM pitching WHERE WAR IS NOT NULL ) combined GROUP BY player_ID, name_common, year_ID ), negative_seasons AS ( SELECT player_ID, name_common, year_ID, season_war, year_ID - ROW_NUMBER() OVER (PARTITION BY player_ID ORDER BY year_ID) AS grp FROM all_war WHERE season_war < 0 ), streaks AS ( SELECT player_ID, MAX(name_common) AS name_common, grp, COUNT(*) AS consecutive_negative_seasons, MIN(year_ID) AS streak_start, MAX(year_ID) AS streak_end FROM negative_seasons GROUP BY player_ID, grp ) SELECT '[' || name_common || '](https://www.baseball-reference.com/players/' || LOWER(LEFT(player_ID, 1)) || '/' || player_ID || '.shtml)' AS player, consecutive_negative_seasons, streak_start, streak_end FROM streaks ORDER BY consecutive_negative_seasons DESC, streak_start LIMIT 500
